    self, domain_name: str, action: Literal["enable", "disable"]
) -> None:
    """
    Updates the enabled domain lists for the given domain name

    :param domain_name:
    :param action:
    :return:
    :rtype:
    """
    if action not in ("enable", "disable"):
        return
    try:
